package com.sharehope.event.repository;
import com.sharehope.event.model.Event; import jakarta.persistence.LockModeType; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import java.util.*;
public interface EventRepository extends JpaRepository<Event,UUID>{List<Event> findAllByOrderByStartAtAscDisplayOrderAsc();List<Event> findByStatusOrderByStartAtAscDisplayOrderAsc(String status);Optional<Event> findBySlug(String slug);@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select e from Event e where e.slug = :slug")Optional<Event> findBySlugForRegistration(@Param("slug")String slug);boolean existsBySlugAndIdNot(String slug,UUID id);}
